(function () {
'use strict';
const $ = (selector) => document.querySelector(selector);
const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
let recognition = null;
let listening = false;
let finalTranscript = '';
function setText(selector, value) {
const element = $(selector);
if (element) element.textContent = value;
}
function setListeningState(active) {
listening = active;
document.body.classList.toggle('ai-speech-listening', active);
const mic = $('#aiSpeechMicBtn');
const toggle = $('#aiSpeechToggleBtn');
const floatingMic = $('#aiFloatingMicBtn');
if (mic) {
mic.classList.toggle('is-listening', active);
mic.setAttribute('aria-pressed', active ? 'true' : 'false');
mic.querySelector('span').textContent = active ? 'Dừng nghe' : 'Bắt đầu nghe';
}
if (toggle) {
toggle.classList.toggle('is-listening', active);
toggle.setAttribute('aria-pressed', active ? 'true' : 'false');
}
if (floatingMic) {
floatingMic.classList.toggle('is-listening', active);
floatingMic.setAttribute('aria-pressed', active ? 'true' : 'false');
}
}
function publishTranscript(text, isFinal) {
document.dispatchEvent(new CustomEvent('tenant:ai-speech-transcript', {
detail: {
text,
final: Boolean(isFinal),
source: 'browser-speech-recognition',
},
}));
}
function appendFinalTranscript(text) {
const normalized = String(text || '').trim();
if (!normalized) return;
finalTranscript = [finalTranscript, normalized].filter(Boolean).join(' ').trim();
const output = $('#aiSpeechText');
if (output) {
output.value = finalTranscript;
output.dispatchEvent(new Event('input', { bubbles: true }));
}
publishTranscript(finalTranscript, true);
}
function ensureRecognition() {
if (!SpeechRecognition) return null;
if (recognition) return recognition;
recognition = new SpeechRecognition();
recognition.lang = 'vi-VN';
recognition.continuous = true;
recognition.interimResults = true;
recognition.onstart = function () {
setListeningState(true);
setText('#aiSpeechStatus', 'Đang nghe...');
};
recognition.onend = function () {
setListeningState(false);
setText('#aiSpeechStatus', finalTranscript ? 'Đã dừng nghe.' : 'Sẵn sàng.');
};
recognition.onerror = function (event) {
setListeningState(false);
setText('#aiSpeechStatus', event.error === 'not-allowed' ? 'Trình duyệt chưa được cấp quyền micro.' : 'Không nhận được giọng nói.');
};
recognition.onresult = function (event) {
let interim = '';
for (let i = event.resultIndex; i < event.results.length; i += 1) {
const transcript = event.results[i][0] ? event.results[i][0].transcript : '';
if (event.results[i].isFinal) appendFinalTranscript(transcript);
else interim += transcript;
}
if (interim.trim()) {
setText('#aiSpeechStatus', 'Đang nghe: ' + interim.trim());
publishTranscript(interim.trim(), false);
}
};
return recognition;
}
function setPanelMinimized(minimized) {
const panel = $('#aiSpeechPanel');
const button = $('#aiSpeechMinimizeBtn');
if (!panel) return;
panel.classList.toggle('is-minimized', minimized);
panel.setAttribute('aria-expanded', minimized ? 'false' : 'true');
if (button) {
button.setAttribute('aria-label', minimized ? 'Mở rộng' : 'Thu nhỏ');
button.setAttribute('title', minimized ? 'Mở rộng' : 'Thu nhỏ');
button.innerHTML = minimized ? '<i class="fa-solid fa-up-right-and-down-left-from-center"></i>' : '<i class="fa-solid fa-minus"></i>';
}
}
function openPanel(options) {
const panel = $('#aiSpeechPanel');
if (!panel) return;
panel.classList.remove('d-none');
setPanelMinimized(false);
panel.setAttribute('aria-hidden', 'false');
const output = $('#aiSpeechText');
if (output) output.focus();
if (options && options.listen) toggleListening();
}
function closePanel() {
const panel = $('#aiSpeechPanel');
if (!panel) return;
if (listening && recognition) recognition.stop();
panel.classList.add('d-none');
panel.setAttribute('aria-hidden', 'true');
setPanelMinimized(false);
}
function toggleMinimized() {
const panel = $('#aiSpeechPanel');
if (!panel) return;
setPanelMinimized(!panel.classList.contains('is-minimized'));
}
function openAndListen() {
openPanel({ listen: !listening });
}
function toggleListening() {
const engine = ensureRecognition();
if (!engine) {
setText('#aiSpeechStatus', 'Trình duyệt không hỗ trợ nhập giọng nói.');
return;
}
try {
if (listening) engine.stop();
else engine.start();
} catch (error) {
setListeningState(false);
setText('#aiSpeechStatus', 'Không thể khởi động micro.');
}
}
function bind() {
const toggle = $('#aiSpeechToggleBtn');
const mic = $('#aiSpeechMicBtn');
const floatingMic = $('#aiFloatingMicBtn');
const close = $('#aiSpeechCloseBtn');
const minimize = $('#aiSpeechMinimizeBtn');
const clear = $('#aiSpeechClearBtn');
const output = $('#aiSpeechText');
if (!toggle || !mic || !output) return;
toggle.addEventListener('click', openPanel);
if (floatingMic) floatingMic.addEventListener('click', openAndListen);
mic.addEventListener('click', toggleListening);
if (close) close.addEventListener('click', closePanel);
if (minimize) minimize.addEventListener('click', toggleMinimized);
if (clear) {
clear.addEventListener('click', function () {
finalTranscript = '';
output.value = '';
setText('#aiSpeechStatus', SpeechRecognition ? 'Sẵn sàng.' : 'Trình duyệt không hỗ trợ nhập giọng nói.');
publishTranscript('', true);
});
}
output.addEventListener('input', function () {
finalTranscript = output.value.trim();
});
setText('#aiSpeechStatus', SpeechRecognition ? 'Sẵn sàng.' : 'Trình duyệt không hỗ trợ nhập giọng nói.');
mic.disabled = !SpeechRecognition;
if (floatingMic) {
floatingMic.disabled = !SpeechRecognition;
floatingMic.setAttribute('aria-pressed', 'false');
}
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bind);
else bind();
})();
